// TH15 synthetic bullet aliases (subset copied from transcribe/th15/touhou-bullets.ecl).
// Native type 20 = OVAL; target slot 672, base radius 7, valid colors 0..7.
const TH15_OVAL: int = 672;

// TH15 v1.00b Extra stage, MainSub07 wave entry (st07.ecl.txt:1276-1279).
// Source: $I0=8 / $I1=1 / $I2=1; enmCreate("GirlD04", 0.0, -48.0, 10000, 1000, 0).
// Only the first GirlD04 group is kept; the other two MainSub07 groups are separate cards.
// Chapter gating (-9905/ENM_CNT), drops, death callback and birth animation are omitted
// per the task and the shared TH16/TH18 transcription policy.
//
// Frame relation: card frame 0 = MainSub07 entry. The shell spends OPENING_BUFFER=120
// frames before spawning the source enemy, so the source attack starts at card frame 120.
// New target tasks first-run one frame late, giving ~2-3 frames of startup offset.
//
// Source/card correspondence is noted at the code that implements each source block.

const TIME_LIMIT: int = 2824;      // 120 opening + 2700 wave window + 4 startup margin
const OPENING_BUFFER: int = 120;

// Source GirlD04_at:0884/0889: %A = %A - 3.883222f (radians) after every ring.
// 3.883222 rad * 65536 / (2*pi) = 40503.47 BAM.
const ANGLE_STEP_BAM: int = 40503;

// Source GirlD04_at:0871 etEx(type 0x100=OFFSCREEN, a=360, b=0) and
// 0881/0886 etExSet(type 0x8=ANGLE_ACCEL, a=120, r=0.01, s=+/-0.017453292 rad/frame).
// Target: offscreen_keep(360), constant angular velocity +/-1 deg/frame and
// tangential acceleration 0.01 px/frame^2 for 120 frames, then stop both.
// Birth ANIM (type 0x2, a=1) is omitted; its 4*initial-speed retreat is folded into sh_dist.
xformdef GIRL_SPIN(dir: angle) {
    offscreen_keep(360);
    set_ang_vel(dir);
    set_accel(0.01fx);
    wait(120);
    set_ang_vel(0deg);
    set_accel(0fx);
}

// Source GirlD04_at:0861-0897.
async sub girl_at() {
    wait(60);                                  // 0864
    var a: int = rand(65536) - 32768;          // 0874 %A = %RANDRAD, [-180,180) deg
    var b: int = -1;                           // 0875
    var c: int = 1000;                         // 0876
    sh_reset(0);                               // 0865 etNew(0)
    sh_sprite(0, TH15_OVAL, 3);                // 0867 etSprite(0, 20, 3)
    sh_aim(0, 0);                              // 0866 etAim(0, 3): fixed-direction ring
    sh_ring(0, 1);
    sh_speed(0, 2fx, 0fx);                     // 0870 etSpeed(2.0, 0.2), 1 layer -> 2.0
    // 0873 etDist(24) plus ANIM a=1 retreat 4*2.0 = 8 along -velocity -> net 16 px.
    sh_dist(0, 16fx);
    while c > 0 {                              // 0895 if ($C--)
        c = c - 1;
        b = b + 1;                             // 0879
        sh_count(0, self_int(0), 1);           // 0868/0880 etCount(I0, 1)
        sh_angle(0, a as angle, 0deg);         // 0882 etAngle(%A, 0)
        sh_xform(0, GIRL_SPIN(1deg));          // 0881 s = +0.017453292
        sh_fire(0);                            // 0883
        a = a - ANGLE_STEP_BAM;                // 0884
        wait(20);                              // 0885
        sh_count(0, self_int(0), 1);
        sh_angle(0, a as angle, 0deg);         // 0887
        sh_xform(0, GIRL_SPIN(-1deg));         // 0886 s = -0.017453292
        sh_fire(0);                            // 0888
        a = a - ANGLE_STEP_BAM;                // 0889
        wait(20);                              // 0890
        if (b % 7) == 6 && self_int(0) < 32 {  // 0891-0893
            set_self_int(0, self_int(0) + 1);
        }
    }
}

// Source GirlD04:0820-0844.
async sub girl_main() {
    set_invuln(65535);                         // training shell: enemy never dies to DPS
    set_hurtbox(16fx);                         // 0826 setHurtbox(32,32) circular -> r=16
    set_hitbox(12fx);                          // 0827 setHitbox(24,24) circular -> r=12
    set_self_int(0, 8);                        // MainSub07:1276 inherited $I0 = 8
    move_vel(0, 90deg, 4.7fx, EASE_LINEAR);    // 0829 moveVel(pi/2, 4.7)
    move_speed(60, 0fx, EASE_QUAD_IN);         // 0830 moveSpeedTime(60, mode1, 0.0)
    spawn girl_at();                           // 0831 @GirlD04_at() async
    wait(1200);                                // 0832
    move_vel(0, -90deg, 0fx, EASE_LINEAR);     // 0833 moveVel(-pi/2, 0.0)
    move_speed(60, 0.5fx, EASE_QUAD_IN);       // 0834 moveSpeedTime(60, mode1, 0.5)
    wait(600);                                 // 0835
    move_speed(80, 1fx, EASE_QUAD_IN);         // 0836 moveSpeedTime(80, mode1, 1.0)
    wait(60);                                  // 0837
    loop { wait(1000); }                       // 0838-0842
}

// Training shell: control enemy carries the phase timer; it has no body and is invulnerable.
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, -48fx, 10000, 0, 0, 0, girl_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
